/**
 * A tiny, valid fragmented MP4 "init only" segment (ftyp + moov + mvex, no
 * media samples). Serving this in place of an ad segment keeps the player's
 * MediaSource timeline alive without decoding ad audio/video.
 *
 * Constant taken from TwitchAdSolutions (MIT), Copyright (c) 2020-present
 * TwitchAdSolutions Contributors. See NOTICE.
 */
const BLANK_MEDIA_BASE64 =
  '';

let cachedBytes: Uint8Array<ArrayBuffer> | null = null;

export function blankMediaBytes(): Uint8Array<ArrayBuffer> {
  if (!cachedBytes) {
    const binary = atob(BLANK_MEDIA_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    cachedBytes = bytes;
  }
  return cachedBytes;
}

export function createBlankMediaBlob(): Blob {
  return new Blob([blankMediaBytes()], { type: 'video/mp4' });
}

export { BLANK_MEDIA_BASE64 };
